import type { AsamResourceServices } from '@asam-ui/pro/components';
import type {
	EditorPageDocument,
	EditorPageHost,
	EditorPageTarget,
	EditorPageWriteResult
} from '../../../templates/editors/Types.js';

export type FixtureMode = 'success' | 'not-written' | 'unknown' | 'throw' | 'late';
export const sampleText =
	'编辑工作页保留原始正文与明确保存结果。每次编辑都有独立身份与版本，加载失败不会覆盖本地修改，未知结果由宿主沿原操作核实。图像只保留稳定地址，页面预览复用公开安全路径。空白、中文、标点和未知语法均按原文保存。';
export function sampleValue(kind: 'richtext', imageUrl?: string): AsamEditorDocument;
export function sampleValue(kind: 'markdown', imageUrl?: string): string;
export function sampleValue(
	kind: 'richtext' | 'markdown',
	imageUrl = '/fixture.svg'
): AsamEditorDocument | string {
	if (kind === 'markdown')
		return (
			'# 编辑说明\n\n' +
			Array.from(
				{ length: 22 },
				(_, index) => `第 ${index + 1} 段：${sampleText.repeat(2)}`
			).join('\n\n') +
			`\n\n- 原文保存\n- 明确反馈\n\n[文档链接](https://example.com)\n\n![本地图像](${imageUrl})\n\n:::unknown\n<script>原文不执行</script>\n`
		);
	const paragraphs: AsamEditorNode[] = Array.from({ length: 22 }, (_, index) => ({
		type: 'paragraph',
		content: [{ type: 'text', text: `第 ${index + 1} 段：${sampleText.repeat(2)}` }]
	}));
	return {
		type: 'doc',
		content: [
			{
				type: 'heading',
				attrs: { level: 1 },
				content: [{ type: 'text', text: '富文本编辑说明' }]
			},
			...paragraphs,
			{
				type: 'bulletList',
				content: [
					{
						type: 'listItem',
						content: [
							{
								type: 'paragraph',
								content: [{ type: 'text', text: '原生 JSON 保存' }]
							}
						]
					}
				]
			},
			{
				type: 'paragraph',
				content: [
					{
						type: 'text',
						text: '文档链接',
						marks: [{ type: 'link', attrs: { href: 'https://example.com' } }]
					}
				]
			},
			{ type: 'image', attrs: { src: imageUrl, alt: '本地图像' } }
		]
	};
}
function websiteRichText(): AsamEditorDocument {
	const text = (value: string) => ({ type: 'text', text: value });
	const paragraph = (value: string) => ({ type: 'paragraph', content: [text(value)] });
	const heading = (value: string, level: number) => ({
		type: 'heading',
		attrs: { level },
		content: [text(value)]
	});
	return {
		type: 'doc',
		content: [
			heading('项目交接说明', 1),
			paragraph(
				'这份文档记录项目进度、待办事项和交付资料。接手同事可以据此确认范围与下一步安排。'
			),
			heading('当前进度', 2),
			paragraph(
				'供应链协同平台已完成第一轮联调。项目范围和接口说明已确认，当前等待验收反馈。'
			),
			{
				type: 'blockquote',
				content: [paragraph('上线前先核对权限、测试数据和回退步骤，再安排发布时间。')]
			},
			heading('待办事项', 2),
			{
				type: 'orderedList',
				content: ['确认测试环境的权限和菜单配置。', '补齐验收记录，更新交付清单。'].map(
					(item) => ({
						type: 'listItem',
						content: [paragraph(item)]
					})
				)
			},
			heading('交付资料', 2),
			paragraph('项目资料统一放在交付目录。更新说明时请注明受影响的模块和版本。')
		]
	};
}
const key = (target: EditorPageTarget) =>
	JSON.stringify([
		target.identity,
		target.scope,
		typeof target.documentId,
		target.documentId,
		target.kind
	]);
const copy = (document: EditorPageDocument): EditorPageDocument =>
	({
		identity: document.identity,
		scope: document.scope,
		documentId: document.documentId,
		kind: document.kind,
		revision: document.revision,
		value: cloneAsamEditorValue(document.kind, document.value)
	}) as EditorPageDocument;
export function createFixtureHost(imageUrl?: string, website = false) {
	const records = new Map<string, EditorPageDocument>();
	const operations = new Map<string, EditorPageWriteResult>();
	const calls: { method: string; target: EditorPageTarget; operationId?: string }[] = [];
	const controls = {
		loadFail: false,
		mode: 'success' as FixtureMode,
		allowDiscard: false,
		uploadFail: false,
		uploadLate: false,
		delayMs: 100
	};
	const wait = (signal: AbortSignal, late = false) =>
		new Promise<void>((resolve, reject) => {
			if (signal.aborted && !late) {
				reject(new Error('操作已取消'));
				return;
			}
			const abort = () => {
				clearTimeout(timer);
				reject(new Error('操作已取消'));
			};
			const timer = setTimeout(() => {
				signal.removeEventListener('abort', abort);
				resolve();
			}, controls.delayMs);
			if (!late) signal.addEventListener('abort', abort, { once: true });
		});
	const host: EditorPageHost = {
		async load({ target, signal }) {
			calls.push({ method: 'load', target: { ...target } });
			await wait(signal);
			if (controls.loadFail) throw new Error('合成加载失败');
			let document = records.get(key(target));
			if (!document) {
				document =
					target.kind === 'richtext'
						? {
								...target,
								kind: 'richtext',
								value: website
									? websiteRichText()
									: sampleValue('richtext', imageUrl)
							}
						: { ...target, kind: 'markdown', value: sampleValue('markdown', imageUrl) };
				records.set(key(target), copy(document));
			}
			if (document.revision !== target.revision) throw new Error('合成版本冲突');
			return copy(document);
		},
		async save(input) {
			const mode = controls.mode;
			const document = copy(input);
			const target: EditorPageTarget = {
				identity: input.identity,
				scope: input.scope,
				documentId: input.documentId,
				kind: input.kind,
				revision: input.revision
			};
			calls.push({ method: 'save', target, operationId: input.operationId });
			await wait(input.signal, mode === 'late');
			if (mode === 'throw') throw new Error('合成传输中断');
			if (mode === 'not-written')
				return {
					target,
					operationId: input.operationId,
					status: 'not-written',
					message: '合成服务明确未写入，请显式重试'
				};
			const previous = records.get(key(input));
			if (previous && previous.revision !== input.revision)
				return {
					target,
					operationId: input.operationId,
					status: 'not-written',
					message: '合成版本冲突，未写入'
				};
			const revision =
				typeof input.revision === 'number' ? input.revision + 1 : `${input.revision}.next`;
			records.set(key(input), copy({ ...document, revision }));
			const saved: EditorPageWriteResult = {
				target,
				operationId: input.operationId,
				status: 'saved',
				revision
			};
			operations.set(input.operationId, saved);
			return mode === 'unknown'
				? {
						target,
						operationId: input.operationId,
						status: 'unknown',
						message: '合成服务已受理，响应未知'
					}
				: saved;
		},
		async verify({ target, operationId, signal }) {
			calls.push({ method: 'verify', target: { ...target }, operationId });
			await wait(signal);
			return (
				operations.get(operationId) ?? {
					target: { ...target },
					operationId,
					status: 'unknown',
					message: '合成服务尚未核实'
				}
			);
		},
		confirmDiscard: () => controls.allowDiscard
	};
	const resources: AsamResourceServices = {
		async upload({ file, signal, progress }) {
			const fail = controls.uploadFail;
			await wait(signal, controls.uploadLate);
			progress(60);
			if (fail) throw new Error('合成资源上传失败');
			progress(100);
			return {
				id: 0,
				name: file.name,
				url: imageUrl ?? new URL('/fixture.svg', location.origin).href,
				size: file.size,
				mimeType: file.type
			};
		}
	};
	return {
		host,
		resources,
		controls,
		calls,
		initialDocumentId: website ? 'PRJ-2026-018' : 0,
		initialRevision: website ? 3 : 0,
		snapshot: () => Array.from(records.values(), copy)
	};
}
